-- Fixtures and fault cases are local-only and rolled back.
begin;
\ir helpers/auth-session.psql
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
create function pg_temp.expect(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'H06 acceptance: %',label; end if; end $$;
create function pg_temp.command(org uuid,op text,input jsonb,req uuid default gen_random_uuid()) returns jsonb language plpgsql as $$ declare r jsonb; begin r:=public.h03_command(org,req,op,input); if not coalesce((r->>'ok')::boolean,false) then raise exception 'H06 %: %',op,r; end if; return r->'data'; end $$;
\ir helpers/document-upload.psql
do $$
declare org uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); client uuid:=gen_random_uuid(); company uuid; actor_member uuid; client_member uuid; role_id uuid; internal_role uuid;
  today date:=(now() at time zone 'America/Lima')::date; input jsonb; result jsonb; request_id uuid:=gen_random_uuid(); activity uuid; internal_activity uuid; recurring uuid; cycle uuid;
  notification uuid; digest public.whatsapp_digests; claim jsonb; receipt jsonb; original jsonb; before_count integer; new_count integer;
  fixture_intent uuid; fixture_slot public.deliverables;
  observed_event uuid; reserved_digest public.whatsapp_digests; pending_digest public.whatsapp_digests;
begin
  insert into auth.users(id,email) values(actor,'h06-a-'||actor||'@example.test'),(client,'h06-c-'||client||'@example.test');
  insert into public.profiles(user_id,email,full_name,provisioning_status,whatsapp_phone) select id,email,'H06 SQL fixture','ready','+15005550006' from auth.users where id in(actor,client);
  insert into public.organizations(id,name) values(org,'H06 Docker SQL');
  -- Allow this transport fixture before 09:00 Lima too; production defaults stay unchanged.
  update public.organizations set settings=jsonb_set(settings,'{digest_local_time}','"00:00"') where id=org;
  insert into public.organization_members(organization_id,user_id,member_type,is_admin) values(org,actor,'internal',true) returning id into actor_member;
  insert into public.organization_members(organization_id,user_id,member_type) values(org,client,'client') returning id into client_member;
  insert into public.companies(organization_id,ruc,legal_name,control_start_date) values(org,'20999999666','H06 SQL company',today-30) returning id into company;
  insert into public.permissions(organization_id,module,action,description) select org,'actividades',a,a from unnest(array['view','upload','download','approve','observe','reopen']) a;
  insert into public.roles(organization_id,code,name,audience) values(org,'h06_client','Client','client') returning id into role_id;
  insert into public.role_permissions(organization_id,role_id,permission_id) select org,role_id,p.id from public.permissions p where p.organization_id=org and p.action in ('view','upload','download');
  insert into public.access_grants(organization_id,member_id,scope,company_id,module,role_id) values(org,client_member,'company',company,'actividades',role_id);
  insert into public.roles(organization_id,code,name,audience) values(org,'h06_internal','Internal','internal') returning id into internal_role;
  insert into public.role_permissions(organization_id,role_id,permission_id) select org,internal_role,p.id from public.permissions p where p.organization_id=org;
  insert into public.access_grants(organization_id,member_id,scope,company_id,module,role_id) values(org,actor_member,'company',company,'actividades',internal_role),(org,actor_member,'organization',null,'actividades',internal_role);
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  input:=jsonb_build_object('company_id',company,'title','H06 additional','description','Private description must not reach WhatsApp','delivery_responsible_id',client,'frequency','unica','due_date',today+7,'priority','alta','max_file_bytes',20000000,'allowed_formats','["pdf"]'::jsonb,
    'deliverable_specs','[{"position_code":"file_1","label":"Required file","display_order":1,"allowed_formats":["pdf"],"max_file_bytes":20000000}]'::jsonb);
  result:=public.h03_command(org,gen_random_uuid(),'CreateAdditionalActivity',input||'{"deliverable_specs":[]}');
  perform pg_temp.expect(result->'error'->>'code'='VALIDATION_ERROR','additional needs at least one file');
  result:=public.h03_command(org,gen_random_uuid(),'CreateAdditionalActivity',input-'max_file_bytes');
  perform pg_temp.expect(result->'error'->>'code'='VALIDATION_ERROR','missing size limit fails at input boundary');
  result:=pg_temp.command(org,'CreateAdditionalActivity',input,request_id); activity:=(result->>'resource_id')::uuid;
  perform pg_temp.expect((pg_temp.command(org,'CreateAdditionalActivity',input,request_id)->>'resource_id')::uuid=activity,'same request returns same activity');
  perform pg_temp.expect((select class='additional' and module='actividades' and rule_id is null from public.obligations where id=activity),'unique additional uses original obligation table without rule');
  perform pg_temp.expect((select count(*)=1 from public.deliverables where obligation_id=activity),'additional has real document positions');
  original:=(select snapshot from public.obligations where id=activity);
  result:=pg_temp.command(org,'CreateAdditionalActivity',input||jsonb_build_object('company_id',null,'title','Internal H06','delivery_responsible_id',actor)); internal_activity:=(result->>'resource_id')::uuid;
  perform pg_temp.expect((select snapshot->'destination'->>'scope'='organization' and company_id is null from public.obligations where id=internal_activity),'internal destination is the organization');
  result:=public.h07_query(org,'audit','{"scope":"internal","module":"actividades","action":"CreateAdditionalActivity"}');
  perform pg_temp.expect(result->'data'->>'count'='1' and result->'data'->'rows'->0->'company_id'='null'::jsonb,'internal audit retains null company and activities module without mixing company events');
  result:=pg_temp.command(org,'CreateAdditionalActivity',input||jsonb_build_object('company_id',null,'delivery_responsible_id',actor,'frequency','semanal','deadline_offset_days',2,'title','Internal weekly H06'));
  perform pg_temp.expect((select count(*)=1 and bool_and(company_id is null and class='additional') from public.obligations where rule_id=(result->>'rule_id')::uuid),'internal recurrence emits an organization-scoped occurrence');
  result:=pg_temp.command(org,'CreateAdditionalActivity',input||jsonb_build_object('frequency','mensual','deadline_offset_days',3,'title','Recurring H06','anchor_date',null)); recurring:=(result->>'rule_id')::uuid;
  perform pg_temp.expect(recurring is not null and (select count(*)=1 from public.obligations where rule_id=recurring),'recurring additional uses H04 rule and first occurrence');
  perform private.h04_generate(recurring,actor,gen_random_uuid(),today,50);
  perform pg_temp.expect((select count(*)=1 from public.obligations where rule_id=recurring),'repeated generation is idempotent');
  original:=(select snapshot from public.obligations where rule_id=recurring limit 1);
  result:=pg_temp.command(org,'ConfigureAdditionalRequirement',input||jsonb_build_object('id',recurring,'expected_revision',(select revision from public.requirement_rules where id=recurring),'frequency','mensual','deadline_offset_days',4,'priority','baja','title','Updated additional','inherit_responsible',false,'is_required',true,'active',true));
  perform pg_temp.expect((select count(*)=2 from public.rule_versions where rule_id=recurring),'additional edit appends a version');
  perform pg_temp.expect((select snapshot=original from public.obligations where rule_id=recurring limit 1),'additional edit preserves emitted snapshot');
  result:=pg_temp.command(org,'DeleteDocumentEntity',jsonb_build_object('entity','requirement_rules','id',recurring,'expected_revision',(select revision from public.requirement_rules where id=recurring),'reason','Logical local deletion'));
  perform pg_temp.expect((select deleted_at is not null from public.requirement_rules where id=recurring) and (select count(*)=1 from public.obligations where rule_id=recurring),'additional rule deletion preserves obligations');
  result:=pg_temp.command(org,'RestoreDocumentEntity',jsonb_build_object('entity','requirement_rules','id',recurring,'expected_revision',(select revision from public.requirement_rules where id=recurring),'reason','Restore local rule'));
  perform pg_temp.expect((select deleted_at is null from public.requirement_rules where id=recurring),'additional rule restores with eligible parents and responsible');
  original:=(select snapshot from public.obligations where id=activity);
  perform pg_temp.authenticate(jsonb_build_object('sub',client,'role','authenticated','session_id',gen_random_uuid())::text,true);
  result:=public.h03_command(org,gen_random_uuid(),'CreateAdditionalActivity',input);
  perform pg_temp.expect(result->'error'->>'code'='FORBIDDEN','client cannot create additional');
  result:=public.h06_query(org,'activities','{"group":"all","pageSize":100}');
  perform pg_temp.expect((result->'data'->>'count')::integer=2,'client sees only two company activities');
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(result->'data'->'rows') r where (r->>'id')::uuid=internal_activity),'client has no internal inbox item');
  perform pg_temp.expect(result->'data'->'indicators'->'documentary'->>'required'='0' and result->'data'->'indicators'->'additional'->>'required'='2','indicators have independent denominators');
  perform pg_temp.expect((public.h03_query(org,'detail',jsonb_build_object('id',internal_activity))->'error'->>'code')='NOT_FOUND','direct internal RPC checks scope');
  select c.id into cycle from public.submission_cycles c join public.deliverables d on d.id=c.deliverable_id where d.obligation_id=activity;
  perform public.h06_run_deadlines(today,org,100); perform public.h06_run_deadlines(today,org,100);
  perform pg_temp.expect((select count(*)=1 from public.notification_events where organization_id=org and cycle_id=cycle and threshold_days=7),'deadline threshold is unique after repeated job');
  perform public.h06_run_deadlines(today+4,org,100); perform public.h06_run_deadlines(today+6,org,100); perform public.h06_run_deadlines(today+7,org,100); perform public.h06_run_deadlines(today+8,org,100);
  perform pg_temp.expect((select count(*)=5 from public.notification_events where organization_id=org and cycle_id=cycle),'all five cycle thresholds have distinct events');
  select id into notification from public.notifications where organization_id=org and recipient_id=client limit 1;
  result:=public.h03_command(org,gen_random_uuid(),'MarkNotificationRead',jsonb_build_object('notification_id',(select id from public.notifications where organization_id=org and recipient_id=actor limit 1)));
  perform pg_temp.expect(result->'error'->>'code'='NOT_FOUND','client cannot mark another recipient notice read');
  perform pg_temp.command(org,'MarkNotificationRead',jsonb_build_object('notification_id',notification));
  perform pg_temp.expect((select read_at is not null from public.notifications where id=notification) and (select disposition='active' from public.obligations where id=activity),'reading changes only notice, not obligation');
  update public.submission_cycles set due_date=today-1 where id=cycle;
  result:=public.h06_query(org,'activities','{"group":"all"}');
  perform pg_temp.expect(result->'data'->'rows'->0->>'id'=activity::text,'overdue open delivery comes first');
  perform public.h06_prepare_digests('https://app.example.test',today,now());
  select * into digest from public.whatsapp_digests where organization_id=org and recipient_id=client and local_date=today;
  perform pg_temp.expect(digest.id is not null and jsonb_array_length(digest.payload->'items')>0,'eligible summary is nonempty');
  perform pg_temp.expect(not (digest.payload::text like '%Private description%') and not (digest.payload::text like '%reference_salary%'),'outgoing summary excludes private description and salary');
  perform public.h06_prepare_digests('https://app.example.test',today,now());
  perform pg_temp.expect((select count(*)=1 from public.whatsapp_digests where organization_id=org and recipient_id=client and local_date=today),'one summary per local day and user');
  claim:=public.h06_gateway_claim(digest.delivery_id,digest.payload-array['schema_version','timezone']);
  perform pg_temp.expect((claim->>'send')::boolean,'first durable claim can call provider');
  perform pg_temp.expect(not (public.h06_gateway_claim(digest.delivery_id,digest.payload-array['schema_version','timezone'])->>'send')::boolean,'second claim cannot call provider after restart');
  receipt:=jsonb_build_object('schema_version','1.0','receipt_id',claim->>'receipt_id','delivery_id',digest.delivery_id,'status','delivered','occurred_at',now(),'provider_message_id','h06-provider-proof');
  perform public.h06_gateway_complete(digest.delivery_id,(claim->>'claim_id')::uuid,receipt);
  perform pg_temp.expect((select status='accepted' from public.whatsapp_digests where id=digest.id),'gateway evidence is saved before callback; accepted is not delivered');
  perform public.h06_receive_receipt(receipt);
  perform pg_temp.expect((select status='delivered' from public.whatsapp_digests where id=digest.id),'provider receipt confirms delivery');
  perform pg_temp.expect((public.h06_receive_receipt(receipt)->>'duplicate')::boolean,'duplicate receipt is replayed');
  perform public.h06_receive_receipt(receipt||jsonb_build_object('receipt_id',gen_random_uuid(),'status','sent','occurred_at',now()-interval '1 minute'));
  perform pg_temp.expect((select status='delivered' from public.whatsapp_digests where id=digest.id),'late sent callback cannot degrade delivered');
  perform pg_temp.expect((select count(*)=2 from public.integration_attempts where digest_id=digest.id and direction='callback'),'duplicate callback adds no second log entry');
  begin
    perform public.h06_receive_receipt(receipt||jsonb_build_object('provider_message_id','conflicting-provider'));
    raise exception 'Conflicting receipt was accepted';
  exception when raise_exception then
    if sqlerrm<>'CONFLICT' then raise; end if;
  end;
  select d.* into fixture_slot from public.deliverables d join public.submission_cycles c on c.deliverable_id=d.id where c.id=cycle;
  result:=pg_temp.command(org,'CreateUploadIntent',jsonb_build_object('deliverable_id',fixture_slot.id,'cycle_id',cycle,'expected_revision',fixture_slot.revision,'original_name','h06-observed.pdf','declared_bytes',200,'declared_mime','application/pdf'));
  fixture_intent:=(result->>'resource_id')::uuid;
  perform pg_temp.confirm(fixture_intent,client,((current_setting('request.jwt.claims')::jsonb)->>'session_id')::uuid);
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  select * into fixture_slot from public.deliverables where id=fixture_slot.id;
  perform pg_temp.command(org,'ObserveVersion',jsonb_build_object('deliverable_id',fixture_slot.id,'version_id',fixture_slot.current_version_id,'expected_revision',fixture_slot.revision,'comment','Private observation fixture','new_due_date',today+7));
  select id into cycle from public.submission_cycles where deliverable_id=fixture_slot.id and state='open';
  select id into observed_event from public.notification_events where organization_id=org and event_type='observed' and cycle_id=cycle;
  perform pg_temp.expect((select (private.h06_observation_cycle(jsonb_populate_record(null::public.notification_events,to_jsonb(e)||jsonb_build_object('cycle_id',(select v.cycle_id from public.review_events r join public.document_versions v on v.id=r.version_id where r.id=e.review_event_id))))).id=cycle from public.notification_events e where e.id=observed_event),'legacy observed event resolves its correction without rewriting history');
  perform pg_temp.expect(exists(select 1 from jsonb_array_elements(private.h06_digest_items(org,client,today+1,'https://app.example.test')) i where i->>'notification_event_id'=observed_event::text),'new unresolved observation is eligible');
  perform public.h06_prepare_digests('https://app.example.test',today+1,now()+interval '1 day');
  select * into reserved_digest from public.whatsapp_digests where organization_id=org and recipient_id=client and local_date=today+1;
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(private.h06_digest_items(org,client,today+2,'https://app.example.test')) i where i->>'notification_event_id'=observed_event::text),'pending digest reserves its observation');
  update public.whatsapp_digests set status='unknown',accepted_at=now(),last_error_code='PROVIDER_AMBIGUOUS' where id=reserved_digest.id;
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(private.h06_digest_items(org,client,today+2,'https://app.example.test')) i where i->>'notification_event_id'=observed_event::text),'unknown provider result keeps observation reserved');
  perform public.h06_prepare_digests('https://app.example.test',today+2,now()+interval '2 days');
  select * into pending_digest from public.whatsapp_digests where organization_id=org and recipient_id=client and local_date=today+2;
  perform pg_temp.expect(pending_digest.id is not null,'open overdue may legitimately recur on another day');
  perform public.h06_prepare_digests('https://app.example.test',today+3,now()+interval '3 days');
  perform pg_temp.expect((select expired_at is not null and payload=pending_digest.payload from public.whatsapp_digests where id=pending_digest.id),'next day expires unaccepted pending without changing frozen payload');
  perform pg_temp.expect((select expired_at is null and status='unknown' from public.whatsapp_digests where id=reserved_digest.id),'unknown is not silently expired or resent');
  update public.profiles set whatsapp_phone=null where user_id=client;
  perform public.h06_prepare_digests('https://app.example.test',today+4,now()+interval '4 days');
  perform pg_temp.expect(not exists(select 1 from public.whatsapp_digests where organization_id=org and recipient_id=client and local_date=today+4),'missing phone creates no false send');
  perform pg_temp.expect(exists(select 1 from public.notification_events where organization_id=org and event_type='contact_issue'),'missing phone has an administrative incident');
  update public.profiles set whatsapp_phone='+15005550006' where user_id=client;
  update public.submission_cycles set first_submitted_at=now(),state='submitted' where id=cycle;
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(private.h06_digest_items(org,client,today+5,'https://app.example.test')) i where i->>'notification_event_id'=observed_event::text),'received correction excludes resolved observation');
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(private.h06_digest_items(org,client,today+1,'https://app.example.test')) i where i->>'obligation_id'=activity::text),'received cycle stops reminders regardless of approval');
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  update public.access_grants set active=false where organization_id=org and member_id=client_member;
  perform public.h06_run_deadlines(today,org,100);
  perform pg_temp.expect((select assignment_issue from public.obligations where id=activity),'removed permission is an assignment issue');
  perform pg_temp.expect((select snapshot=original from public.obligations where id=activity),'assignment incident preserves frozen snapshot');
  perform pg_temp.expect(jsonb_array_length(private.h06_digest_items(org,client,today+5,'https://app.example.test'))=0,'retired delivery permission removes all recipient items');
  perform public.h06_prepare_digests('https://app.example.test',today+5,now()+interval '5 days');
  perform pg_temp.expect(not exists(select 1 from public.whatsapp_digests where organization_id=org and recipient_id=client and local_date=today+5),'empty eligible set creates no daily message');
  result:=pg_temp.command(org,'ReassignDelivery',jsonb_build_object('obligation_id',activity,'delivery_responsible_id',actor,'expected_revision',(select revision from public.obligations where id=activity),'reason','Reassign retired local fixture'));
  perform pg_temp.expect((select delivery_responsible_id=actor and not assignment_issue from public.obligations where id=activity),'eligible reassignment resolves assignment incident');
  perform pg_temp.expect(not has_table_privilege('authenticated','public.notifications','SELECT'),'Realtime does not require exposing notice rows');
  perform pg_temp.expect(not has_function_privilege('authenticated','public.h06_prepare_digests(text,date,timestamp with time zone)','EXECUTE'),'browser cannot execute daily preparation');
end $$;
select extensions.pass('H06 additional activities, internal scope, shared recurrence, inbox, thresholds, reads, durable gateway and provider receipts');
select * from extensions.finish();
rollback;
